-- Упражнения книги 19, глава 4 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-pri-decode', 0, 'func', 'Число PRI', 'Сообщение сислога начинается с числа PRI в угловых скобках, например <165>. PRI = категория × 8 + приоритет. Имена категорий по номерам 0–23: kern, user, mail, daemon, auth, syslog, lpr, news, uucp, cron, authpriv, ftp, ntp, audit, alert, clock, local0, local1, local2, local3, local4, local5, local6, local7. Имена приоритетов 0–7: emerg, alert, crit, err, warning, notice, info, debug. Напишите функцию decode_pri(line): верните кортеж (категория, приоритет) по началу строки. Корректное PRI — от одной до трёх цифр между < и > в самом начале строки, без ведущих нулей (кроме одиночного <0>), значение не больше 191. В остальных случаях верните None.', 'def decode_pri(line):
    pass
', 'Проверьте скобки и цифры через регулярное выражение ^<(\d{1,3})>, затем divmod(value, 8).', '{"func": "decode_pri", "tests": [{"args": ["<165>Nov  3 09:15:02 web01 app: hello"], "expected": {"__tuple__": ["local4", "notice"]}}, {"args": ["<34>Oct 11 22:14:15 mymachine su: ''su root'' failed on /dev/pts/8"], "expected": {"__tuple__": ["auth", "crit"]}}, {"args": ["<86>Nov  3 09:15:02 web01 sshd[7]: Accepted publickey"], "expected": {"__tuple__": ["authpriv", "info"]}}, {"args": ["<0>kernel panic"], "expected": {"__tuple__": ["kern", "emerg"]}}, {"args": ["<191>x"], "expected": {"__tuple__": ["local7", "debug"]}}, {"args": ["<14>Mar  5 10:00:00 h cron: ok"], "expected": {"__tuple__": ["user", "info"]}}, {"args": ["<192>x"], "expected": null}, {"args": ["<013>x"], "expected": null}, {"args": ["<>x"], "expected": null}, {"args": ["<1234>x"], "expected": null}, {"args": ["Nov  3 09:15:02 web01 app: <13> inside"], "expected": null}, {"args": [" <13>x"], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-syslog-parse', 1, 'func', 'Строка сислога', 'Файлы вроде /var/log/syslog хранят строки в виде «Mmm dd hh:mm:ss хост метка[pid]: текст». Напишите функцию parse_syslog(line): верните словарь с ключами month (число 1–12), day (число), time (строка hh:mm:ss), host, tag, pid (число или None) и msg. Правила: месяц — трёхбуквенное английское имя с заглавной буквы (Jan … Dec); день занимает ровно два символа — пробел или цифра, затем цифра (Nov  3 и Nov 13), значение 1–31; затем один пробел, время из цифр hh:mm:ss, один пробел, хост без пробелов, один пробел. Метка — один или несколько символов, кроме пробелов, [, ] и :; за ней необязательно идёт [pid] из одних цифр, затем обязательно двоеточие. Сообщение — всё после двоеточия, из которого удалён один начальный пробел, если он есть (сообщение может быть пустым). Если строка не подходит под этот формат, верните None.', 'def parse_syslog(line):
    pass
', 'Одно регулярное выражение с группами решает почти всё; не забудьте проверить день 1–31 и вернуть pid как int.', '{"func": "parse_syslog", "tests": [{"args": ["Nov  3 09:15:02 web01 sshd[1234]: Failed password for root from 10.0.0.5 port 4242 ssh2"], "expected": {"month": 11, "day": 3, "time": "09:15:02", "host": "web01", "tag": "sshd", "pid": 1234, "msg": "Failed password for root from 10.0.0.5 port 4242 ssh2"}}, {"args": ["Dec 25 00:00:01 db-2 CRON[981]: (root) CMD (run-parts /etc/cron.hourly)"], "expected": {"month": 12, "day": 25, "time": "00:00:01", "host": "db-2", "tag": "CRON", "pid": 981, "msg": "(root) CMD (run-parts /etc/cron.hourly)"}}, {"args": ["Jan  9 23:59:59 lb kernel: [  123.456789] eth0: link up"], "expected": {"month": 1, "day": 9, "time": "23:59:59", "host": "lb", "tag": "kernel", "pid": null, "msg": "[  123.456789] eth0: link up"}}, {"args": ["Mar  1 10:00:00 host systemd-logind[512]: New session 3 of user admin."], "expected": {"month": 3, "day": 1, "time": "10:00:00", "host": "host", "tag": "systemd-logind", "pid": 512, "msg": "New session 3 of user admin."}}, {"args": ["Nov  3 09:15:02 web01 sudo:    admin : TTY=pts/0 ; PWD=/home/admin ; USER=root ; COMMAND=/bin/ls"], "expected": {"month": 11, "day": 3, "time": "09:15:02", "host": "web01", "tag": "sudo", "pid": null, "msg": "   admin : TTY=pts/0 ; PWD=/home/admin ; USER=root ; COMMAND=/bin/ls"}}, {"args": ["Nov 12 09:15:02 web01 app[77]:"], "expected": {"month": 11, "day": 12, "time": "09:15:02", "host": "web01", "tag": "app", "pid": 77, "msg": ""}}, {"args": ["Nov 3 09:15:02 web01 sshd[1]: x"], "expected": null}, {"args": ["Foo  3 09:15:02 web01 sshd[1]: x"], "expected": null}, {"args": ["Nov  0 09:15:02 web01 sshd[1]: x"], "expected": null}, {"args": ["Nov  3 09:15:02 web01 last message repeated 2 times"], "expected": null}, {"args": ["Nov  3 09:15:02 web01 app[x]: msg"], "expected": null}, {"args": ["Nov  3 09:15 web01 app[1]: msg"], "expected": null}, {"args": [""], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-rsyslog-route', 2, 'func', 'Куда попадёт сообщение', 'Правила rsyslog в традиционной записи: строка «селекторы действие». Селекторы пишутся без пробелов и разделяются точкой с запятой; каждый селектор — «категории.приоритет», категории через запятую или *. Приоритет: имя из списка emerg, alert, crit, err, warning, notice, info, debug (от самого серьёзного), * (любой), none (никакой) или имя с префиксами: «=имя» — ровно этот уровень, «!имя» — этот и все серьёзнее исключаются, «!=имя» — исключается ровно этот. Обычное имя означает этот уровень и все серьёзнее. Селекторы строки применяются слева направо: сначала сообщение «не выбрано»; селектор, к которому подходят категория и приоритет сообщения, выбирает его, если он обычный, и снимает выбор, если приоритет none или начинается с !. Строка с файловым действием (действие начинается с / или с -/; путь кончается на первой точке с запятой, если после неё идёт шаблон) отправляет сообщение в этот файл, если оно выбрано; минус перед путём не входит в путь. Остальные строки (пустые, комментарии с #, директивы вроде $FileOwner или module(...), действия :omusrmsg:* и т. п.) игнорируйте. Напишите функцию route_rsyslog(config, facility, severity): верните отсортированный список уникальных путей файлов, куда попадёт сообщение.', 'def route_rsyslog(config, facility, severity):
    pass
', 'Разберите строку по первому пробелу; для каждого селектора заведите флаг selected и меняйте его слева направо. Приоритеты сравнивайте по индексу в списке.', '{"func": "route_rsyslog", "tests": [{"args": ["# /etc/rsyslog.conf (fragment)\nmodule(load=\"imuxsock\")\n$FileOwner root\nauth,authpriv.*                 /var/log/auth.log\n*.*;auth,authpriv.none          -/var/log/syslog\nkern.*                          -/var/log/kern.log\nmail.err                        /var/log/mail.err\n*.emerg                         :omusrmsg:*\nlocal5.=info;local5.!=info      /var/log/never.log\ncron.*;mail.!=info              /var/log/cron-mail.log\nmail.*;mail.!=info              /var/log/mail-noinfo.log\n", "auth", "info"], "expected": ["/var/log/auth.log"]}, {"args": ["# /etc/rsyslog.conf (fragment)\nmodule(load=\"imuxsock\")\n$FileOwner root\nauth,authpriv.*                 /var/log/auth.log\n*.*;auth,authpriv.none          -/var/log/syslog\nkern.*                          -/var/log/kern.log\nmail.err                        /var/log/mail.err\n*.emerg                         :omusrmsg:*\nlocal5.=info;local5.!=info      /var/log/never.log\ncron.*;mail.!=info              /var/log/cron-mail.log\nmail.*;mail.!=info              /var/log/mail-noinfo.log\n", "daemon", "err"], "expected": ["/var/log/syslog"]}, {"args": ["# /etc/rsyslog.conf (fragment)\nmodule(load=\"imuxsock\")\n$FileOwner root\nauth,authpriv.*                 /var/log/auth.log\n*.*;auth,authpriv.none          -/var/log/syslog\nkern.*                          -/var/log/kern.log\nmail.err                        /var/log/mail.err\n*.emerg                         :omusrmsg:*\nlocal5.=info;local5.!=info      /var/log/never.log\ncron.*;mail.!=info              /var/log/cron-mail.log\nmail.*;mail.!=info              /var/log/mail-noinfo.log\n", "mail", "err"], "expected": ["/var/log/mail-noinfo.log", "/var/log/mail.err", "/var/log/syslog"]}, {"args": ["# /etc/rsyslog.conf (fragment)\nmodule(load=\"imuxsock\")\n$FileOwner root\nauth,authpriv.*                 /var/log/auth.log\n*.*;auth,authpriv.none          -/var/log/syslog\nkern.*                          -/var/log/kern.log\nmail.err                        /var/log/mail.err\n*.emerg                         :omusrmsg:*\nlocal5.=info;local5.!=info      /var/log/never.log\ncron.*;mail.!=info              /var/log/cron-mail.log\nmail.*;mail.!=info              /var/log/mail-noinfo.log\n", "mail", "warning"], "expected": ["/var/log/mail-noinfo.log", "/var/log/syslog"]}, {"args": ["# /etc/rsyslog.conf (fragment)\nmodule(load=\"imuxsock\")\n$FileOwner root\nauth,authpriv.*                 /var/log/auth.log\n*.*;auth,authpriv.none          -/var/log/syslog\nkern.*                          -/var/log/kern.log\nmail.err                        /var/log/mail.err\n*.emerg                         :omusrmsg:*\nlocal5.=info;local5.!=info      /var/log/never.log\ncron.*;mail.!=info              /var/log/cron-mail.log\nmail.*;mail.!=info              /var/log/mail-noinfo.log\n", "mail", "info"], "expected": ["/var/log/syslog"]}, {"args": ["# /etc/rsyslog.conf (fragment)\nmodule(load=\"imuxsock\")\n$FileOwner root\nauth,authpriv.*                 /var/log/auth.log\n*.*;auth,authpriv.none          -/var/log/syslog\nkern.*                          -/var/log/kern.log\nmail.err                        /var/log/mail.err\n*.emerg                         :omusrmsg:*\nlocal5.=info;local5.!=info      /var/log/never.log\ncron.*;mail.!=info              /var/log/cron-mail.log\nmail.*;mail.!=info              /var/log/mail-noinfo.log\n", "kern", "debug"], "expected": ["/var/log/kern.log", "/var/log/syslog"]}, {"args": ["# /etc/rsyslog.conf (fragment)\nmodule(load=\"imuxsock\")\n$FileOwner root\nauth,authpriv.*                 /var/log/auth.log\n*.*;auth,authpriv.none          -/var/log/syslog\nkern.*                          -/var/log/kern.log\nmail.err                        /var/log/mail.err\n*.emerg                         :omusrmsg:*\nlocal5.=info;local5.!=info      /var/log/never.log\ncron.*;mail.!=info              /var/log/cron-mail.log\nmail.*;mail.!=info              /var/log/mail-noinfo.log\n", "local5", "info"], "expected": ["/var/log/syslog"]}, {"args": ["# /etc/rsyslog.conf (fragment)\nmodule(load=\"imuxsock\")\n$FileOwner root\nauth,authpriv.*                 /var/log/auth.log\n*.*;auth,authpriv.none          -/var/log/syslog\nkern.*                          -/var/log/kern.log\nmail.err                        /var/log/mail.err\n*.emerg                         :omusrmsg:*\nlocal5.=info;local5.!=info      /var/log/never.log\ncron.*;mail.!=info              /var/log/cron-mail.log\nmail.*;mail.!=info              /var/log/mail-noinfo.log\n", "cron", "info"], "expected": ["/var/log/cron-mail.log", "/var/log/syslog"]}, {"args": ["*.info;mail.none;authpriv.none;cron.none                /var/log/messages;RSYSLOG_TraditionalFileFormat\nauthpriv.*                                              /var/log/secure\nmail.*                                                  -/var/log/maillog\ncron.*                                                  /var/log/cron\n*.emerg                                                 :omusrmsg:*\nuucp,news.crit                                          /var/log/spooler\nlocal7.*                                                /var/log/boot.log\n", "daemon", "info"], "expected": ["/var/log/messages"]}, {"args": ["*.info;mail.none;authpriv.none;cron.none                /var/log/messages;RSYSLOG_TraditionalFileFormat\nauthpriv.*                                              /var/log/secure\nmail.*                                                  -/var/log/maillog\ncron.*                                                  /var/log/cron\n*.emerg                                                 :omusrmsg:*\nuucp,news.crit                                          /var/log/spooler\nlocal7.*                                                /var/log/boot.log\n", "daemon", "debug"], "expected": []}, {"args": ["*.info;mail.none;authpriv.none;cron.none                /var/log/messages;RSYSLOG_TraditionalFileFormat\nauthpriv.*                                              /var/log/secure\nmail.*                                                  -/var/log/maillog\ncron.*                                                  /var/log/cron\n*.emerg                                                 :omusrmsg:*\nuucp,news.crit                                          /var/log/spooler\nlocal7.*                                                /var/log/boot.log\n", "authpriv", "info"], "expected": ["/var/log/secure"]}, {"args": ["*.info;mail.none;authpriv.none;cron.none                /var/log/messages;RSYSLOG_TraditionalFileFormat\nauthpriv.*                                              /var/log/secure\nmail.*                                                  -/var/log/maillog\ncron.*                                                  /var/log/cron\n*.emerg                                                 :omusrmsg:*\nuucp,news.crit                                          /var/log/spooler\nlocal7.*                                                /var/log/boot.log\n", "mail", "err"], "expected": ["/var/log/maillog"]}, {"args": ["*.info;mail.none;authpriv.none;cron.none                /var/log/messages;RSYSLOG_TraditionalFileFormat\nauthpriv.*                                              /var/log/secure\nmail.*                                                  -/var/log/maillog\ncron.*                                                  /var/log/cron\n*.emerg                                                 :omusrmsg:*\nuucp,news.crit                                          /var/log/spooler\nlocal7.*                                                /var/log/boot.log\n", "news", "crit"], "expected": ["/var/log/messages", "/var/log/spooler"]}, {"args": ["*.info;mail.none;authpriv.none;cron.none                /var/log/messages;RSYSLOG_TraditionalFileFormat\nauthpriv.*                                              /var/log/secure\nmail.*                                                  -/var/log/maillog\ncron.*                                                  /var/log/cron\n*.emerg                                                 :omusrmsg:*\nuucp,news.crit                                          /var/log/spooler\nlocal7.*                                                /var/log/boot.log\n", "uucp", "warning"], "expected": ["/var/log/messages"]}, {"args": ["*.info;mail.none;authpriv.none;cron.none                /var/log/messages;RSYSLOG_TraditionalFileFormat\nauthpriv.*                                              /var/log/secure\nmail.*                                                  -/var/log/maillog\ncron.*                                                  /var/log/cron\n*.emerg                                                 :omusrmsg:*\nuucp,news.crit                                          /var/log/spooler\nlocal7.*                                                /var/log/boot.log\n", "local7", "debug"], "expected": ["/var/log/boot.log"]}, {"args": ["", "user", "info"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-journal-filter', 3, 'func', 'Фильтр journalctl -o json', 'Команда journalctl -o json печатает по одному JSON-объекту на строку; значения почти всех полей — строки: PRIORITY ("0"–"7"), __REALTIME_TIMESTAMP (микросекунды с эпохи), _BOOT_ID, _SYSTEMD_UNIT, UNIT, MESSAGE. Поле MESSAGE бывает массивом чисел-байтов (неотображаемые данные: декодируйте его как UTF-8 с заменой ошибок) или null (считайте пустой строкой); _SYSTEMD_UNIT и UNIT могут отсутствовать. Напишите функцию journal_filter(lines, unit, prio, boot, since, until): lines — список строк JSON. Запись проходит, если выполнены все заданные условия: unit — пустая строка (любой) или совпадает с _SYSTEMD_UNIT либо с UNIT (так -u находит и сообщения менеджера об этом юните); prio — пустая строка, либо один уровень (имя emerg, alert, crit, err, warning, notice, info, debug или цифра), тогда подходят записи этого уровня и серьёзнее (PRIORITY не больше), либо диапазон «от..до» (имена или цифры, первым более серьёзный), оба края включительно; boot — пустая строка или значение _BOOT_ID; since и until — микросекунды или None: подходят записи с since <= время < until. Верните список текстов MESSAGE подходящих записей, упорядоченный по времени (при равном времени — как во входе).', 'def journal_filter(lines, unit, prio, boot, since, until):
    pass
', 'Разберите каждую строку через json.loads; уровни переводите в числа словарём имён; отсортируйте пары (время, номер строки).', '{"func": "journal_filter", "tests": [{"args": [["{\"_BOOT_ID\" : \"a1b2c3d4e5f60718293a4b5c6d7e8f90\", \"PRIORITY\" : \"6\", \"_SYSTEMD_UNIT\" : \"nginx.service\", \"SYSLOG_IDENTIFIER\" : \"nginx\", \"_PID\" : \"812\", \"MESSAGE\" : \"Started nginx\", \"__REALTIME_TIMESTAMP\" : \"1709625000000000\", \"__CURSOR\" : \"s=0;i=1\"}", "{\"_BOOT_ID\" : \"a1b2c3d4e5f60718293a4b5c6d7e8f90\", \"PRIORITY\" : \"3\", \"_SYSTEMD_UNIT\" : \"nginx.service\", \"SYSLOG_IDENTIFIER\" : \"nginx\", \"_PID\" : \"812\", \"MESSAGE\" : \"connect() failed (111: Connection refused)\", \"__REALTIME_TIMESTAMP\" : \"1709625010000000\", \"__CURSOR\" : \"s=0;i=11\"}", "{\"_BOOT_ID\" : \"a1b2c3d4e5f60718293a4b5c6d7e8f90\", \"PRIORITY\" : \"4\", \"_SYSTEMD_UNIT\" : \"sshd.service\", \"SYSLOG_IDENTIFIER\" : \"sshd\", \"_PID\" : \"812\", \"MESSAGE\" : \"Failed password for root from 10.0.0.5\", \"__REALTIME_TIMESTAMP\" : \"1709625020000000\", \"__CURSOR\" : \"s=0;i=21\"}", "{\"_BOOT_ID\" : \"a1b2c3d4e5f60718293a4b5c6d7e8f90\", \"PRIORITY\" : \"5\", \"_SYSTEMD_UNIT\" : \"nginx.service\", \"SYSLOG_IDENTIFIER\" : \"nginx\", \"_PID\" : \"812\", \"MESSAGE\" : \"worker process 4021 exited\", \"__REALTIME_TIMESTAMP\" : \"1709625030000000\", \"__CURSOR\" : \"s=0;i=31\"}", "{\"_BOOT_ID\" : \"a1b2c3d4e5f60718293a4b5c6d7e8f90\", \"PRIORITY\" : \"4\", \"SYSLOG_IDENTIFIER\" : \"kernel\", \"_PID\" : \"812\", \"MESSAGE\" : \"EXT4-fs warning: mounting fs with errors\", \"__REALTIME_TIMESTAMP\" : \"1709625040000000\", \"__CURSOR\" : \"s=0;i=41\"}", "{\"_BOOT_ID\" : \"a1b2c3d4e5f60718293a4b5c6d7e8f90\", \"PRIORITY\" : \"6\", \"_SYSTEMD_UNIT\" : \"init.scope\", \"UNIT\" : \"nginx.service\", \"SYSLOG_IDENTIFIER\" : \"systemd\", \"_PID\" : \"812\", \"MESSAGE\" : \"Stopping nginx.service\", \"__REALTIME_TIMESTAMP\" : \"1709625050000000\", \"__CURSOR\" : \"s=0;i=51\"}", "{\"_BOOT_ID\" : \"0f1e2d3