INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-first-failure', 4, 'func', 'Первая ошибка и её соседи', 'Вывод journalctl -o short-iso состоит из строк «2024-03-05T10:15:01+0000 хост метка[pid]: текст» (pid необязателен, как и в сислоге); между загрузками встречаются служебные строки вроде «-- Boot ... --». Строки другого вида пропускайте. Напишите функцию first_failure(lines, keywords, window): ошибочной считается строка, в тексте которой встречается любое из слов keywords (поиск без учёта регистра, слова заданы в нижнем регистре). Найдите первую ошибочную строку (строки идут в хронологическом порядке) и верните кортеж (время первой ошибки так, как оно записано в строке, её метка, список меток других юнитов). Список состоит из различных меток, отличных от метки первой ошибки, у ошибочных строк, чьё время (с учётом смещения часового пояса) не раньше времени первой ошибки и не позже, чем через window секунд после неё включительно; метки идут в порядке первого появления. Если ошибок нет, верните None.', 'def first_failure(lines, keywords, window):
    pass
