:2048000kB", "2024-03-05T10:15:02+0000 app01 postgresql[601]: FATAL:  terminating connection due to administrator command", "2024-03-05T10:15:03+0000 app01 postgresql[601]: server process (PID 4021) was terminated by signal 9", "2024-03-05T10:15:05+0000 app01 myapp[900]: ERROR: database connection lost", "2024-03-05T10:15:09+0000 app01 systemd[1]: myapp.service: Main process exited, code=exited, status=1/FAILURE", "2024-03-05T10:16:00+0000 app01 sshd[1500]: error: PAM: Authentication failure for admin"], ["error", "failed", "failure", "fatal", "out of memory"], 120], "expected": {"__tuple__": ["2024-03-05T10:15:01+0000", "kernel", ["postgresql", "myapp", "systemd", "sshd"]]}}, {"args": [["-- Boot 5d2c9e1b7a3f4c08a1b2c3d4e5f60718 --", "2024-03-05T10:14:58+0000 app01 postgresql[601]: checkpoint complete: wrote 213 buffers"], ["error", "failed", "failure", "fatal", "out of memory"], 30], "expected": null}, {"args": [[], ["error", "failed", "failure", "fatal", "out of memory"], 30], "expected": null}, {"args": [["2024-03-05T12:00:00+0200 h a[1]: Error: disk", "2024-03-05T10:00:20+0000 h b: error again", "2024-03-05T12:00:45+0200 h c: failed", "2024-03-05T12:00:20+0000 h d: error"], ["error", "failed"], 30], "expected": {"__tuple__": ["2024-03-05T12:00:00+0200", "a", ["b"]]}}, {"args": [["2024-03-05T10:00:00+0000 error-host failed-job[3]: started", "2024-03-05T10:00:01+0000 h unit: Timeout"], ["error", "failed"], 10], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-boot-resolve', 5, 'func', 'Загрузка по номеру или времени', 'Вывод journalctl --list-boots — это таблица: строка заголовка («IDX BOOT ID FIRST ENTRY LAST ENTRY») и по строке на загрузку, от самой старой к самой новой. Строка загрузки начинается с целого числа (колонка IDX, её значение игнорируйте: порядок определяет позиция), затем идёт 32-символьный шестнадцатеричный boot id, затем два момента времени в виде YYYY-MM-DD hh:mm:ss (первая и последняя записи; день недели, часовой пояс и разделитель между моментами игнорируйте). Остальные строки пропускайте. Напишите функцию resolve_boot(text, spec): если spec — целое число, то по правилу ключа -b: 0 — последняя загрузка, -1 — предыдущая и так далее; положительное число считается с начала (1 — самая первая); если spec — строка «YYYY-MM-DD hh:mm:ss», верните загрузку, у которой первая запись <= spec <= последняя запись. Верните boot id или пустую строку, если такой загрузки нет.', 'def resolve_boot(text, spec):
    pass
', 'Строка загрузки: первое слово — целое, второе — 32 hex-символа; моменты времени ищите re.findall. Строки времени такого формата сравниваются как обычные строки.', '{"func": "resolve_boot", "tests": [{"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", 0], "expected": "d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a"}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", -1], "expected": "8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f"}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", -2], "expected": "3f6f1c0e9a2b4d58b1c7e4a0d9f35b12"}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", -3], "expected": ""}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", 1], "expected": "3f6f1c0e9a2b4d58b1c7e4a0d9f35b12"}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", 3], "expected": "d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a"}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", 4], "expected": ""}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", "2024-03-05 12:00:00"], "expected": "8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f"}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", "2024-03-05 07:58:40"], "expected": "8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f"}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", "2024-03-04 20:00:00"], "expected": ""}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n -2 3f6f1c0e9a2b4d58b1c7e4a0d9f35b12 Mon 2024-03-04 08:00:12 UTC—Mon 2024-03-04 19:41:03 UTC\n -1 8c1d2e3f4a5b4c6d8e7f9a0b1c2d3e4f Tue 2024-03-05 07:58:40 UTC—Tue 2024-03-05 23:59:58 UTC\n  0 d4c3b2a1f0e94d8c9b8a7f6e5d4c3b2a Wed 2024-03-06 08:01:05 UTC—Wed 2024-03-06 12:30:44 UTC\n", "2024-03-06 12:30:45"], "expected": ""}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n  0 0123456789abcdef0123456789abcdef Fri 2024-01-05 10:00:00 UTC — Fri 2024-01-05 10:30:00 UTC\n", "2024-01-05 10:15:00"], "expected": "0123456789abcdef0123456789abcdef"}, {"args": ["IDX BOOT ID                          FIRST ENTRY                  LAST ENTRY\n  0 0123456789abcdef0123456789abcdef Fri 2024-01-05 10:00:00 UTC — Fri 2024-01-05 10:30:00 UTC\n", 0], "expected": "0123456789abcdef0123456789abcdef"}, {"args": ["-- No entries --\n", 0], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-logrotate-files', 6, 'func', 'Какие файлы останутся после ротаций', 'Дан блок logrotate: первая строка «путь {», дальше директивы по одной в строке (пустые строки и строки с # игнорируйте), последняя строка «}». Учитывайте директивы: rotate N (сколько ротированных копий хранить; последняя заданная побеждает; без директивы 0), compress и nocompress (побеждает последняя; сжатый файл получает суффикс .gz), delaycompress (имеет эффект только вместе с compress: самая свежая ротированная копия остаётся несжатой), dateext и nodateext (побеждает последняя). Остальные директивы игнорируйте. Исходно существует только сам журнал. Каждая ротация переименовывает текущий файл в копию и создаёт новый пустой текущий файл. Без dateext копии нумеруются: самая свежая получает номер 1 (путь.1), при каждой ротации номера сдвигаются на единицу, копии с номером больше N удаляются. С dateext имя копии — путь-ДАТА (дата из списка dates, по одной на ротацию, строки YYYYMMDD, по возрастанию и без повторов); хранятся N копий с самыми поздними датами, остальные удаляются. Сжатые копии получают суффикс .gz после номера или даты. Напишите функцию files_after(config, dates): число ротаций равно len(dates); верните отсортированный список путей всех существующих файлов (включая текущий журнал).', 'def files_after(config, dates):
    pass
', 'Храните копии списком от свежей к старой: у каждой есть ключ (номер или дата); после ротации обрежьте список до N и решите, какие копии сжаты.', '{"func": "files_after", "tests": [{"args": ["/var/log/app.log {\n    weekly\n    rotate 3\n    compress\n    delaycompress\n    missingok\n    notifempty\n}\n", []], "expected": ["/var/log/app.log"]}, {"args": ["/var/log/app.log {\n    weekly\n    rotate 3\n    compress\n    delaycompress\n    missingok\n    notifempty\n}\n", ["20240301"]], "expected": ["/var/log/app.log", "/var/log/app.log.1"]}, {"args": ["/var/log/app.log {\n    weekly\n    rotate 3\n    compress\n    delaycompress\n    missingok\n    notifempty\n}\n", ["20240301", "20240302"]], "expected": ["/var/log/app.log", "/var/log/app.log.1", "/var/log/app.log.2.gz"]}, {"args": ["/var/log/app.log {\n    weekly\n    rotate 3\n    compress\n    delaycompress\n    missingok\n    notifempty\n}\n", ["20240301", "20240302", "20240303", "20240304", "20240305"]], "expected": ["/var/log/app.log", "/var/log/app.log.1", "/var/log/app.log.2.gz", "/var/log/app.log.3.gz"]}, {"args": ["/var/log/db.log {\n    rotate 2\n    compress\n}\n", ["a", "b", "c", "d"]], "expected": ["/var/log/db.log", "/var/log/db.log.1.gz", "/var/log/db.log.2.gz"]}, {"args": ["/var/log/web/access.log {\n    # keep a week\n    rotate 5\n\n    rotate 1\n    compress\n    delaycompress\n    dateext\n}\n", ["20240301", "20240302", "20240303"]], "expected": ["/var/log/web/access.log", "/var/log/web/access.log-20240303"]}, {"args": ["/var/log/x.log {\n    rotate 3\n    dateext\n    compress\n    delaycompress\n}\n", ["20240301", "20240302", "20240303", "20240304", "20240305"]], "expected": ["/var/log/x.log", "/var/log/x.log-20240303.gz", "/var/log/x.log-20240304.gz", "/var/log/x.log-20240305"]}, {"args": ["/var/log/x.log {\n    rotate 0\n    compress\n}\n", ["20240301", "20240302"]], "expected": ["/var/log/x.log"]}, {"args": ["/var/log/y.log {\n    rotate 2\n    compress\n    nocompress\n}\n", ["1", "2", "3"]], "expected": ["/var/log/y.log", "/var/log/y.log.1", "/var/log/y.log.2"]}, {"args": ["/var/log/z.log {\n    rotate 4\n    delaycompress\n}\n", ["1", "2", "3"]], "expected": ["/var/log/z.log", "/var/log/z.log.1", "/var/log/z.log.2", "/var/log/z.log.3"]}, {"args": ["/var/log/z.log {\n    rotate 2\n    dateext\n    nodateext\n    compress\n}\n", ["20240301", "20240302", "20240303"]], "expected": ["/var/log/z.log", "/var/log/z.log.1.gz", "/var/log/z.log.2.gz"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-logrotate-should', 7, 'func', 'Пора ли вращать журнал', 'Решите, что logrotate сделает с одним журналом. Дан блок настроек config (директивы по одной в строке, пустые строки и # игнорируйте), размер файла size в байтах (None — файла нет), даты последней ротации last и сегодняшняя today в виде «YYYY-MM-DD». Напишите функцию rotation_decision(config, size, last, today): верните "error" — файла нет и нет missingok; "skip" — файла нет, но есть missingok, либо файл пустой (размер 0) и есть notifempty; иначе "rotate" или "skip" по критерию. Критерии: среди директив daily, weekly, monthly и size N побеждает последняя из них (они взаимоисключающие). daily — вращать, если сегодня другой день, чем last; weekly — если прошло не меньше 7 дней или с last пересечено воскресенье (номер дня недели сегодня, считая воскресенье нулём, меньше, чем у last); monthly — если месяц или год другой, чем у last. size N — вращать, если размер строго больше N, независимо от дат; N это число байт с необязательным суффиксом k, M или G (1024, 1024², 1024³). Дополнения к daily, weekly и monthly: maxsize N — вращать, если размер больше N, даже если срок ещё не пришёл; minsize N — вращать, только если срок пришёл и размер строго больше N. Если ни одного критерия нет, вращайте.', 'def rotation_decision(config, size, last, today):
    pass
', 'Сначала разберите директивы в словарь, затем проверьте файл, затем критерий. Номер дня недели с воскресеньем = 0: (date.weekday() + 1) % 7.', '{"func": "rotation_decision", "tests": [{"args": ["daily\nrotate 7\nmissingok", 100, "2024-03-04", "2024-03-05"], "expected": "rotate"}, {"args": ["daily\nrotate 7", 100, "2024-03-05", "2024-03-05"], "expected": "skip"}, {"args": ["daily\nmissingok", null, "2024-03-04", "2024-03-05"], "expected": "skip"}, {"args": ["daily", null, "2024-03-04", "2024-03-05"], "expected": "error"}, {"args": ["daily\nnotifempty", 0, "2024-03-04", "2024-03-05"], "expected": "skip"}, {"args": ["daily\nifempty", 0, "2024-03-04", "2024-03-05"], "expected": "rotate"}, {"args": ["size 100k", 102400, "2024-03-05", "2024-03-05"], "expected": "skip"}, {"args": ["size 100k", 102401, "2024-03-05", "2024-03-05"], "expected": "rotate"}, {"args": ["size 1M\n# last wins\ndaily", 10, "2024-03-01", "2024-03-05"], "expected": "rotate"}, {"args": ["daily\nsize 1M", 10, "2024-03-01", "2024-03-05"], "expected": "skip"}, {"args": ["weekly", 5, "2024-03-01", "2024-03-04"], "expected": "rotate"}, {"args": ["weekly", 5, "2024-03-04", "2024-03-06"], "expected": "skip"}, {"args": ["weekly", 5, "2024-02-26", "2024-03-04"], "expected": "rotate"}, {"args": ["monthly", 5, "2024-02-29", "2024-03-01"], "expected": "rotate"}, {"args": ["monthly", 5, "2023-03-01", "2024-03-01"], "expected": "rotate"}, {"args": ["monthly", 5, "2024-03-01", "2024-03-31"], "expected": "skip"}, {"args": ["weekly\nmaxsize 10M", 20971520, "2024-03-05", "2024-03-05"], "expected": "rotate"}, {"args": ["weekly\nmaxsize 10M", 1024, "2024-03-05", "2024-03-05"], "expected": "skip"}, {"args": ["daily\nminsize 1G", 1024, "2024-03-04", "2024-03-05"], "expected": "skip"}, {"args": ["daily\nminsize 100", 100, "2024-03-04", "2024-03-05"], "expected": "skip"}, {"args": ["daily\nminsize 100", 101, "2024-03-04", "2024-03-05"], "expected": "rotate"}, {"args": ["compress\nrotate 3", 7, "2024-03-04", "2024-03-05"], "expected": "rotate"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-journal-vacuum', 8, 'func', 'Что вычистит journald', 'Простая модель очистки журнала. Дан список файлов files от старого к новому: кортежи (имя, размер в байтах, активный). Активный файл — тот, в который сейчас пишут; остальные архивные. Заданы SystemMaxUse (max_use), SystemKeepFree (keep_free), текущее свободное место раздела fs_free и SystemMaxFiles (max_files), всё в байтах или штуках. Журнал может занимать не больше allowed = min(max_use, всего + fs_free − keep_free), где всего — сумма размеров всех файлов; если число отрицательное, считайте allowed равным 0. Очистка удаляет только архивные файлы, самые старые первыми, пока одновременно не выполнятся оба условия: сумма размеров оставшихся файлов не больше allowed и файлов не больше max_files. Если архивные файлы закончились, очистка останавливается (активный файл не удаляется). Напишите функцию vacuum_plan(files, max_use, keep_free, fs_free, max_files): верните список имён удалённых файлов в порядке удаления.', 'def vacuum_plan(files, max_use, keep_free, fs_free, max_files):
    pass
', 'Посчитайте allowed один раз по исходной сумме, затем в цикле по архивным файлам удаляйте, пока условия нарушены.', '{"func": "vacuum_plan", "tests": [{"args": [[{"__tuple__": ["a", 40, false]}, {"__tuple__": ["b", 40, false]}, {"__tuple__": ["c", 30, false]}, {"__tuple__": ["d", 20, true]}], 100, 10, 500, 100], "expected": ["a"]}, {"args": [[{"__tuple__": ["a", 40, false]}, {"__tuple__": ["b", 40, false]}, {"__tuple__": ["c", 30, false]}, {"__tuple__": ["d", 20, true]}], 1000, 50, 20, 100], "expected": ["a"]}, {"args": [[{"__tuple__": ["a", 40, false]}, {"__tuple__": ["b", 40, false]}, {"__tuple__": ["c", 30, false]}, {"__tuple__": ["d", 20, true]}], 1000, 50, 0, 100], "expected": ["a", "b"]}, {"args": [[{"__tuple__": ["a", 40, false]}, {"__tuple__": ["b", 40, false]}], 1000, 10, 500, 100], "expected": []}, {"args": [[{"__tuple__": ["a", 10, false]}, {"__tuple__": ["b", 10, false]}, {"__tuple__": ["c", 10, false]}, {"__tuple__": ["d", 10, false]}, {"__tuple__": ["e", 10, true]}], 1000, 0, 1000, 3], "expected": ["a", "b"]}, {"args": [[{"__tuple__": ["a", 50, false]}, {"__tuple__": ["b", 60, true]}], 100, 0, 1000, 100], "expected": ["a"]}, {"args": [[{"__tuple__": ["a", 50, false]}, {"__tuple__": ["b", 500, true]}], 100, 0, 1000, 100], "expected": ["a"]}, {"args": [[{"__tuple__": ["a", 5, false]}, {"__tuple__": ["b", 5, false]}, {"__tuple__": ["c", 5, true]}], 100, 1000, 10, 100], "expected": ["a", "b"]}, {"args": [[], 100, 10, 10, 5], "expected": []}, {"args": [[{"__tuple__": ["a", 10, true]}], 1, 0, 0, 1], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 4, 'la4-rate-limit', 9, 'func', 'Лимит частоты сообщений', 'Модель RateLimitIntervalSec и RateLimitBurst в journald: лимит действует на каждую службу отдельно. Окно лимита начинается с первого принятого сообщения службы; в окне принимаются первые burst сообщений, остальные отбрасываются. Если очередное сообщение пришло позже, чем через interval секунд после начала окна (строго больше), оно открывает новое окно и принимается как первое в нём. Если interval или burst равен 0, лимит выключен и принимаются все сообщения. Напишите функцию rate_limit(events, interval, burst): events — список кортежей (служба, время в секундах), упорядоченный по времени. Верните словарь служба → кортеж (принято, отброшено) для каждой службы, встретившейся во входе.', 'def rate_limit(events, interval, burst):
    pass
', 'Для каждой службы храните начало окна и счётчик сообщений в окне.', '{"func": "rate_limit", "tests": [{"args": [[{"__tuple__": ["a", 0]}, {"__tuple__": ["a", 1]}, {"__tuple__": ["a", 2]}, {"__tuple__": ["a", 3]}], 30, 3], "expected": {"a": {"__tuple__": [3, 1]}}}, {"args": [[{"__tuple__": ["a", 0]}, {"__tuple__": ["a", 1]}, {"__tuple__": ["a", 2]}, {"__tuple__": ["a", 31]}, {"__tuple__": ["a", 32]}], 30, 2], "expected": {"a": {"__tuple__": [4, 1]}}}, {"args": [[{"__tuple__": ["a", 0]}, {"__tuple__": ["b", 0]}, {"__tuple__": ["a", 1]}, {"__tuple__": ["b", 1]}, {"__tuple__": ["a", 2]}], 30, 2], "expected": {"a": {"__tuple__": [2, 1]}, "b": {"__tuple__": [2, 0]}}}, {"args": [[{"__tuple__": ["a", 0]}, {"__tuple__": ["a", 1]}, {"__tuple__": ["a", 2]}], 0, 1], "expected": {"a": {"__tuple__": [3, 0]}}}, {"args": [[{"__tuple__": ["a", 0]}, {"__tuple__": ["a", 1]}, {"__tuple__": ["a", 2]}], 30, 0], "expected": {"a": {"__tuple__": [3, 0]}}}, {"args": [[], 30, 10], "expected": {}}, {"args": [[{"__tuple__": ["a", 0]}, {"__tuple__": ["a", 10]}, {"__tuple__": ["a", 20]}, {"__tuple__": ["a", 29.5]}, {"__tuple__": ["a", 40]}, {"__tuple__": ["a", 41]}], 30, 2], "expected": {"a": {"__tuple__": [4, 2]}}}, {"args": [[{"__tuple__": ["x", 5]}, {"__tuple__": ["x", 5]}, {"__tuple__": ["x", 5]}, {"__tuple__": ["x", 5]}, {"__tuple__": ["x", 5]}], 10, 1], "expected": {"x": {"__tuple__": [1, 4]}}}, {"args": [[{"__tuple__": ["x", 5]}, {"__tuple__": ["x", 5.5]}, {"__tuple__": ["x", 20]}, {"__tuple__": ["x", 20.5]}, {"__tuple__": ["x", 21]}], 10, 10], "expected": {"x": {"__tuple__": [5, 0]}}}]}');
